import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Inscripcion.css';

const Inscripcion = ({ cursoId }) => {
  const navigate = useNavigate();

  // Estado para el formulario
  const [formData, setFormData] = useState({});
  const [formErrors, setFormErrors] = useState({});
  const [preguntas, setPreguntas] = useState([]);
  const [campos, setCampos] = useState([]);

  // Estado para controlar si la inscripción fue exitosa
  const [isInscribed, setIsInscribed] = useState(false);

  // Obtener preguntas y campos desde el backend
  useEffect(() => {
    fetch('http://localhost:3001/api/preguntas-y-campos')
      .then((response) => response.json())
      .then((data) => {
        setPreguntas(data.preguntas);
        setCampos(data.campos);
        
        // Inicializar el estado de formData con los campos recibidos
        const initialFormData = {};
        data.campos.forEach((campo) => {
          initialFormData[campo.nombre] = '';
        });
        setFormData(initialFormData);
      })
      .catch((error) => console.error('Error al obtener datos:', error));
  }, []);

  // Manejar los cambios en los campos del formulario
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  // Validar los campos del formulario
  const validateForm = () => {
    const errors = {};
    campos.forEach((campo) => {
      if (campo.requerido && !formData[campo.nombre]) {
        errors[campo.nombre] = "Este campo es obligatorio";
      }
    });
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // Enviar los datos al backend para crear la inscripción
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    const response = await fetch('http://localhost:3001/api/usuarios/inscribirse', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ...formData,
        cursoId: cursoId, // Enviar el ID del curso seleccionado
      }),
    });

    if (response.ok) {
      setIsInscribed(true);
      setTimeout(() => {
        navigate(`/pago/${cursoId}`); // Redirigir a la página de pago
      }, 2000);
    } else {
      alert('Error al inscribirse');
    }
  };

  return (
    <div className="inscripcion">
      {!isInscribed ? (
        <>
          <h2>Inscripción Gratuita</h2>

          {/* Formulario de Información Personal */}
          <div className="form-container">
            <h3>Información Personal</h3>
            <form onSubmit={handleSubmit} className="form-info-personal">
              {campos.length > 0 && campos.map((campo) => (
                <div key={campo.id} className="form-group">
                  <label htmlFor={campo.nombre}>
                    {campo.etiqueta} <span className="asterisco">{campo.requerido ? '*' : ''}</span>
                  </label>
                  <input
                    type={campo.nombre === 'email' ? 'email' : campo.nombre === 'edad' ? 'number' : 'text'}
                    name={campo.nombre}
                    placeholder={campo.etiqueta}
                    value={formData[campo.nombre]}
                    onChange={handleChange}
                    className={formErrors[campo.nombre] ? 'error' : ''}
                  />
                  {formErrors[campo.nombre] && <p className="error-message">{formErrors[campo.nombre]}</p>}
                </div>
              ))}

              {/* Campos de teléfono (incluyendo prefijo) */}
              <div className="form-group">
                <label htmlFor="telefono">Teléfono <span className="asterisco">*</span></label>
                <div className="telefono-group">
                  <select
                    name="prefijoTelefono"
                    value={formData.prefijoTelefono || '+1'}
                    onChange={handleChange}
                  >
                    <option value="+1">+1 (EE.UU.)</option>
                    <option value="+34">+34 (España)</option>
                    <option value="+44">+44 (Reino Unido)</option>
                    {/* Más prefijos si es necesario */}
                  </select>
                  <input
                    type="text"
                    name="telefono"
                    placeholder="Número de Teléfono"
                    value={formData.telefono}
                    onChange={handleChange}
                    className={formErrors.telefono ? 'error' : ''}
                  />
                </div>
                {formErrors.telefono && <p className="error-message">{formErrors.telefono}</p>}
              </div>
            </form>
          </div>

          {/* Formulario de Información Profesional */}
          <div className="form-container">
            <h3>Información Profesional</h3>
            <form className="form-info-profesional">
              {preguntas.length > 0 && preguntas.map((pregunta) => (
                <div key={pregunta.id}>
                  <p><strong>{pregunta.texto}</strong></p>
                  <div className="opciones">
                    {pregunta.Opciones?.map((opcion) => (
                      <label key={opcion.id}>
                        <input type="radio" name={`pregunta_${pregunta.id}`} value={opcion.id} />
                        {opcion.texto}
                      </label>
                    ))}
                  </div>
                </div>
              ))}
            </form>
          </div>

          {/* Botón de Inscripción */}
          <div className="boton-inscripcion">
            <button type="submit" onClick={handleSubmit}>Inscribirse</button>
          </div>
        </>
      ) : (
        <div className="inscripcion-exitosa">
          <h3>¡Inscripción exitosa!</h3>
        </div>
      )}
    </div>
  );
};

export default Inscripcion;
